	@Test
	void largestGoodInteger()
	{
		String message;
		for (Map.Entry<String, String> entry : MAP.entrySet())
		{
			final String digits = entry.getKey();
			final String expected = entry.getValue();
			final String actual = Largest3SameDigitNumberInAString.largestGoodInteger(digits);

			message = "Test failed for case: " + digits
				+ "\nExpected: " + expected
				+ "\n  Actual: " + actual;

			assertEquals(expected, actual, message);
		}
	}
